apt install -y keepalived && cat > /etc/keepalived/keepalived.conf << 'EOF'
vrrp_instance VI_1 {
  interface eth0
  state MASTER
  virtual_router_id 51
  priority 100
  advert_int 1
  authentication { auth_type PASS; auth_pass mypass; }
  virtual_ipaddress { 192.168.1.200/24 dev eth0 }
}
EOF && systemctl restart keepalived

apt install -y nginx-extras && echo -e 'location / {
  auth_ldap "Restricted";
  auth_ldap_servers ldap1;
  proxy_pass http://backend;
}' >> /etc/nginx/sites-available/default

apt install -y passenger libnginx-mod-http-passenger && echo -e 'passenger_root /usr/lib/ruby/vendor_ruby/phusion_passenger/locations.ini;
server {
  listen 80;
  root /var/www/myapp/public;
  passenger_enabled on;
}' > /etc/nginx/sites-available/passenger && nginx -s reload
